import {freshState,escapeHTML as h} from './model.js?v=0.31.0';
import {curiosity,priorities} from './content.js?v=0.31.0';
import {availableFamilies,careerOptions,selectCareer,createPlanActions,applyGuidePay,lifestylePreset} from './guide-state.js?v=0.31.0';
import {careerConnection,taskPrompts} from './matching.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
import {formatSalary,salaryPreviewStages} from './salary-progression.js?v=0.31.0';
import {lifestyleRoom,lifestyleIncomeRange} from './lifestyle-story.js?v=0.31.0';
import {preparationPreview} from './planning-guidance.js?v=0.31.0';
import {clinicalTrainingTimeline,professionalCostPanel,graduateAidPanel} from './education-evidence-ui.js?v=0.31.0';
import {trainingCostPreview} from './profile-ui.js?v=0.31.0';
import {salaryPanel} from './salary-ui.js?v=0.31.0';
export const studentExamples=[
 {id:'medicine',title:'Medicine',themes:{R:3,I:5,A:2,S:4,E:2,C:3},overrides:{2:4,8:4,14:5,16:5,20:3,22:3},priorities:['impact','curiosity','mastery'],family:'health',paths:['medicines-nutrition','nursing-care'],careers:['physician','physician-assistant','nursing'],stage:'residency',loan:1500,project:'Explained a biology topic for a school health club.',reflection:'I enjoy understanding illness and helping people understand it.',watch:'Enjoying biology does not establish readiness for clinical work. Try supervised exposure before committing to a long route.'},
 {id:'dentistry',title:'Dentistry',themes:{R:4,I:4,A:4,S:4,E:2,C:3},overrides:{1:5,7:3,13:3,14:5,16:5,19:2,20:2,22:3,25:3,27:3},priorities:['mastery','impact','stability'],family:'health',paths:['medicines-nutrition','allied-health'],careers:['dentist','dental-hygiene','dental-assisting'],stage:'entry',loan:2000,project:'Made detailed clay models and a biology illustration.',reflection:'I like careful handwork and helping people feel comfortable.',watch:'Dentistry, dental hygiene, and assisting have different scopes and credentials. Hygiene and assisting are alternatives, not automatic steps into dental school.'},
 {id:'creative',title:'Creative work',themes:{R:3,I:3,A:5,S:3,E:2,C:3},overrides:{3:5,9:5,15:5,21:4,27:4,8:2},priorities:['creativity','independence','variety'],family:'creative',paths:['visual-arts','design'],careers:['graphic-design','industrial-design','web-interface-design'],stage:'entry',loan:250,project:'Designed posters and revised them after club feedback.',reflection:'I lose track of time making visual ideas clearer.',watch:'These figures describe employee wages. Freelance revenue must also cover expenses, unpaid time, and benefits. A strong portfolio matters alongside education.'},
 {id:'trades',title:'Skilled trades',themes:{R:5,I:3,A:2,S:3,E:2,C:4},overrides:{1:5,7:5,13:5,19:3,24:5,25:5,14:2},priorities:['mastery','stability','independence'],family:'trades',paths:['skilled-trades'],careers:['electrician','hvac','plumbing'],stage:'apprenticeship',loan:0,project:'Built a safe low-voltage classroom circuit and read its diagram.',reflection:'I enjoy practical troubleshooting and seeing a working result.',watch:'Austin ETA is one competitive apprenticeship example. Its pay schedule is not the regional average. Qualified pay starts after training; hours and overtime vary.'}
];
export function exampleState(id){const e=studentExamples.find(x=>x.id===id)||studentExamples[0],s=freshState();s.profile.nickname='Fictional '+e.title+' student';for(const q of curiosity)s.curiosity[q.id]=e.overrides[Number(q.id.split('-')[1])]??e.themes[q.theme];s.priorities=[...e.priorities];for(const k of ['data','making','communication','investigation'])s.confidence[k]={exposure:k==='making'?'some':'new',confidence:3};s.evidence.project=e.project;s.reflection.energy=e.reflection;Object.assign(s.guide,{entry:'assessment',family:e.family,familyIds:[e.family],path:e.paths[0],pathIds:[...e.paths],taskInterests:e.careers.map(id=>'work:'+id)});for(const [i,id] of e.careers.entries())selectCareer(s,id,{alternative:i>0});s.guide.preparation=occupationById(e.careers[0]).finance?.educationRoutes.routes[0]||'';s.guide.salaryStage=e.stage;s.guide.salaryPicked=true;s.guide.lifestylePreset='alone';s.finance.lifestyle=lifestylePreset('alone');applyGuidePay(s);createPlanActions(s);return s;}
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export function exampleResult(id){const e=studentExamples.find(x=>x.id===id)||studentExamples[0],s=exampleState(e.id),room=lifestyleRoom(s.finance.lifestyle),range=lifestyleIncomeRange(s.finance.lifestyle),stress=lifestyleRoom({...s.finance.lifestyle,debt:String(e.loan)}),shared=lifestyleRoom({...lifestylePreset('shared'),gross:s.finance.lifestyle.gross,debt:String(e.loan)});return {e,s,fields:availableFamilies(s).filter(f=>f.connection.supported).slice(0,3),matches:careerOptions(s).slice(0,3),room,range,stress,shared};}
export function studentExamplesPage(id='medicine'){const {e,s,fields,matches,room,range,stress,shared}=exampleResult(id),primary=occupationById(s.guide.primaryCareer),stage=salaryPreviewStages(primary.id).find(x=>x.key===e.stage);return `<div class="page-intro"><div><span class="eyebrow">FOUR FICTIONAL STUDENT WALKTHROUGHS</span><h1>From interests to a next step.</h1><p>Read-only examples. Your own answers and plan stay yours.</p></div></div><nav class="salary-preview-stages" aria-label="Example students">${studentExamples.map(x=>`<a href="#/student-examples/${x.id}" ${e.id===x.id?'aria-current="page"':''}>${x.title}</a>`).join('')}</nav><p><a href="#/student-examples/mixed">Mixed interests, low confidence, or not sure? See three more students →</a></p><section class="guide-input-panel"><h2>Meet the ${e.title.toLowerCase()} student.</h2><p>${h(e.reflection)}</p><p>${h(e.project)}</p><div class="tags">${e.priorities.map(id=>`<span class="tag">${h(priorities.find(x=>x.id===id).title)}</span>`).join('')}</div><h3>Broad fields worth exploring</h3><div class="tags">${fields.map(f=>`<span class="tag">${h(f.title)}</span>`).join('')}</div><p>These are interest connections. The student then chose ${h(e.family==='health'?'healthcare':e.title.toLowerCase())} and the tasks below.</p></section><div class="guide-career-grid student-example-matches">${matches.map((o,i)=>`<article class="guide-choice ${i===0?'example-chosen':''}"><span class="overline">${i===0?'CHOSEN DIRECTION':'ALSO EXPLORE'}</span><h2>${h(o.finance?.title||o.title)}</h2><p>${h(careerConnection(s,o).reasons[0]||'Explore the daily work.')}</p><p>${h(preparationPreview(o.id)||o.preparation.typicalEducation.join(' or '))}</p><a href="#/career/${o.id}">See career profile →</a></article>`).join('')}</div><section class="guide-input-panel"><span class="eyebrow">THE PERSONAL PLAN</span><h2>${h(primary.finance?.title||primary.title)}</h2><p>${h(s.guide.preparation)}</p>${clinicalTrainingTimeline(primary.id)}<p><strong>${h(e.watch)}</strong></p></section><section class="guide-input-panel example-reality ${room.key}"><h2>The Austin reality check</h2><div class="guide-fact-grid"><article><b>${formatSalary(stage.amount)}</b><p>${h(stage.label)} / year before tax</p></article><article><b>${formatSalary(range.low)}–${formatSalary(range.high)}</b><p>Gross income target for the chosen lifestyle</p></article></div><p>${stage.evidence==='official_entry_proxy'?'Starting pay is a TWC lower-paid-third proxy, not observed first-job pay.':stage.estimate?'Planning illustration.':e.stage==='apprenticeship'?'Published training example. Annual pay assumes 40 paid hours a week.':'Dell Med’s published 2026–27 first-year resident salary.'}</p><h3>${h(room.title)}</h3><p>One adult. A one-bedroom rental. A practical used car. Modest meals, travel, recreation, and savings.</p><p><strong>${room.result.remaining<0?'About '+usd(Math.abs(room.result.remaining))+' short each month.':'About '+usd(room.result.remaining)+' left each month.'}</strong> Before education-loan payments.</p>${e.loan?`<details class="more-info"><summary>What if loan payments are ${usd(e.loan)} a month?</summary><p>This is a stress test, not predicted borrowing or a repayment quote. It leaves ${usd(stress.result.remaining)} each month after the same choices.</p></details>`:''}${['creative','trades'].includes(e.id)?`<details class="more-info"><summary>One possible adjustment: share rent and use transit</summary><p>The optional shared-home example ${shared.result.remaining<0?'still falls short by '+usd(-shared.result.remaining):'leaves about '+usd(shared.result.remaining)} a month${e.loan?' with the loan-payment stress test':''}. Transit must work for the actual job site and hours. You can change other choices instead.</p></details>`:''}<details class="more-info"><summary>Budget assumptions and limits</summary><p>Spending and cash savings: about ${usd(room.result.spending)} a month. Estimated take-home after modeled tax, retirement, and health deductions: ${usd(room.result.takeHome)}. The target range runs from covering these choices to leaving 20% of take-home unallocated. It is a budget target, not a confidence interval. No future inflation or guaranteed raises. Costs and wage source years differ.</p></details></section>${primary.id!=='electrician'?'<section class="guide-input-panel"><h2>College cost references</h2><p>UT Austin resident tuition: $10,858–$13,576 per academic year. ACC in-district tuition and fees: $2,550 for 30 credits.</p><p>2026–27, before aid. Living costs are extra. These are undergraduate reference prices, not quotes for the chosen credential. Grants can reduce price; loans must be repaid.</p><details class="more-info"><summary>Official college budgets</summary><p><a href="https://onestop.utexas.edu/managing-costs/cost-tuition-rates/cost-of-attendance/" target="_blank" rel="noopener">UT Austin budget ↗</a> · <a href="https://students.austincc.edu/financial-aid/explore-your-financial-aid/cost-of-attendance/" target="_blank" rel="noopener">ACC budget ↗</a></p></details></section>':''}${trainingCostPreview(primary.id)}${professionalCostPanel(primary.id)}${graduateAidPanel(primary.id)}<section class="guide-input-panel"><h2>Three useful next steps</h2>${s.actions.map((a,i)=>`<article><h3>${i+1}. ${h(a.title)}</h3><p>${h(a.detail)}</p></article>`).join('')}</section><details class="more-info"><summary>Pay over time and its sources</summary>${salaryPanel(primary.id,{stage:e.stage})}</details><details class="more-info"><summary>Exact questionnaire answers</summary><p>Original reflection prompts, not a validated aptitude test. Ratings: 1 = really not for me; 5 = I’d love this. Confidence is self-reported and does not raise or lower interest matches. Free-text reflections are retained, not scored.</p>${curiosity.map(q=>`<p><strong>${s.curiosity[q.id]} / 5</strong> · ${h(q.text)}</p>`).join('')}<p>Experience: some practice making things; new to the other three activities. Confidence: 3/5 for all four. No measured ability score is inferred.</p><p>Selected tasks order: ${e.careers.map(id=>h(taskPrompts['work:'+id])).join(' Then: ')}</p></details>`;}
